}

/**
 * Add a line to an invoice. If the SKU already exists, increase its quantity.
 * @param {{ status: string, customerId: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, input) {
  const { sku, qty } = input;

  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discountPercent: explicit value wins, otherwise use tier discount
  let discount;
  if ('discountPercent' in input) {
    discount = input.discountPercent;
  } else {
    discount = TIER_DISCOUNTS[customer.tier];
  }

  // Validate discount
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product by SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = [];
  let found = false;

  for (const line of invoice.lines) {
    if (line.sku === sku) {
      newLines.push({
        ...line,
        qty: line.qty + qty,
        discountPercent: discount,
      });
      found = true;
    } else {
      newLines.push({ ...line });
    }
  }

  // If SKU not found, add new line
  if (!found) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if it would remove the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without that line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already in use
 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  const number = numberResult.value;

  // Create new invoice with number and status 'issued'
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

