import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice with one line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  const line = r.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice creates a valid invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[1].qty, 2);
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an invalid date (Feb 30)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-array lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-integer quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(lines[0].sku, 'DES-HOUR');
  assert.equal(lines[0].qty, 5);
  assert.equal(Object.keys(lines[0]).length, 2);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
});

test('lineTotal works with different quantities', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 1000 }), 1000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 2500 }), 25000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 100 }), 10000);
});

test('invoiceTotals calculates the sum of line totals', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 42500);
  assert.equal(r.value.discount, 0);
  // VAT on 42500 at 21% = 8925
  assert.equal(r.value.vat, 8925);
  assert.equal(r.value.total, 42500 + 8925);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 0, discountPercent: 0 },
      { qty: 10, unitPrice: 5000, vatRate: 0, discountPercent: 0 },
      { qty: 2, unitPrice: 15000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 42500 + 50000 + 30000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 122500);
});

test('invoiceTotals rejects invalid invoice (not an object)', () => {
  const r = invoiceTotals(null);
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals rejects invalid invoice (missing lines)', () => {
  const r = invoiceTotals({ customerId: 'C-003' });
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals rejects invalid invoice (lines not an array)', () => {
  const r = invoiceTotals({ lines: null });
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals rejects invalid line (missing qty)', () => {
  const invoice = {
    lines: [
      { unitPrice: 1000 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'INVALID_LINE' });
});

test('invoiceTotals rejects invalid line (missing unitPrice)', () => {
  const invoice = {
    lines: [
      { qty: 5 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'INVALID_LINE' });
});

test('invoiceTotals rejects invalid line (null line)', () => {
  const invoice = {
    lines: [null],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'INVALID_LINE' });
});

test('invoiceTotals works with invoices from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 3, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, (5 + 3) * 8500);
  assert.equal(totals.value.discount, 0);
  // DES-HOUR has 21% VAT, 68000 * 0.21 = 14280
  assert.equal(totals.value.vat, 14280);
  assert.equal(totals.value.total, 68000 + 14280);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].qty, 10);
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 8);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
});

test('addLine does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = invoice.value;
  const originalQty = original.lines[0].qty;

  addLine(original, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(original.lines[0].qty, originalQty);
  assert.equal(original.lines.length, 1);
});

test('addLine rejects if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine rejects invalid qty', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DES-HOUR', qty: 0 });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'UNKNOWN', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('removeLine removes a line from invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = removeLine(invoice.value, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 3);
});

test('removeLine does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  const original = invoice.value;
  const originalLength = original.lines.length;

  removeLine(original, 'DES-HOUR');

  assert.equal(original.lines.length, originalLength);
});

test('removeLine rejects if SKU not on invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = removeLine(invoice.value, 'UNKNOWN');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects if it would remove the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
