  assert.equal(invoice.ok, true);

  const r = removeLine(invoice.value, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('removeLine rejects if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 3, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
    ],
