  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 100 * 8500 = 850000
  // Discount: 850000 * 10% = 85000
  // Amount after discount: 850000 - 85000 = 765000
  // VAT on 765000 at 21% = 160650
  assert.equal(r.value.subtotal, 850000);
  assert.equal(r.value.discount, 85000);
  assert.equal(r.value.vat, 160650);
  assert.equal(r.value.total, 850000 - 85000 + 160650);
});

